  kids: ["Joannes, Jannes (ca. 1759 Ambt Ommen) · kw 68", "Gerrit Nijmeijer (ca. 1765 – 1838 Vilsteren), landbouwer"],
  res: [{ p: "Vilsteren", y: 1765, t: "het gezin woonde vermoedelijk in Vilsteren of elders in het Ambt Ommen" }],
  notes: ["Zijn zoon Jannes droeg zijn naam als patroniem: Joannes Derks."],
