  notes: ["In 1786 was ze als 'Elizabeth Fonk' meter bij haar kleindochter en naamgenote Elizabeth in Steggerda."],
  m: { w: "Frans Alberts Vonk", d: "1754-05-12", p: "Steggerda" },
