  notes: [{ t: "Een Phimmigjen Ruurds was in 1807 getuige bij het RK-huwelijk van Wytze Jans de Boer en Geertje Bouwman in Oldeholtpade. Of dat zij was, is niet bekend.", k: "hypothese" }],
